<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;700;900&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#d40000;
    --blue:#0033a0;
    --yellow:#f2c400;
    --black:#000000;
    --white:#f4f1ea;
    --grey:#b9b5ac;
    --line:14px;
  }
  *{margin:0;padding:0;box-sizing:border-box;}
  html{scroll-behavior:smooth;}
  body{
    font-family:'Archivo',sans-serif;
    background:var(--white);
    color:var(--black);
    line-height:1.55;
  }
  .grid-frame{
    display:grid;
    grid-template-columns:var(--line) 1fr var(--line);
    gap:0;
    min-height:100vh;
  }
  .vline{background:var(--black);}
  /* ---------- HERO ---------- */
  .hero{
    display:grid;
    grid-template-rows:auto 1fr auto;
    min-height:100vh;
    padding:clamp(24px,4vw,56px);
  }
  .hero-top{
    display:grid;
    grid-template-columns:1fr 1fr;
    gap:var(--line);
    align-items:start;
  }
  .kicker{
    font-weight:900;
    text-transform:uppercase;
    letter-spacing:.14em;
    font-size:clamp(.7rem,1.4vw,.95rem);
    background:var(--black);
    color:var(--white);
    padding:.5em 1em;
    justify-self:start;
  }
  .hero-art{
    position:relative;
    aspect-ratio:1/1;
    background:var(--white);
    border:var(--line) solid var(--black);
    display:grid;
    grid-template-columns:1fr 1fr;
    grid-template-rows:1fr 1fr;
    overflow:hidden;
  }
  .hero-art .block{position:absolute;}
  .hero-art .red{
    background:var(--red);
    top:0;right:0;width:50%;height:50%;
    border-left:var(--line) solid var(--black);
    border-bottom:var(--line) solid var(--black);
  }
  .hero-art .blue{
    background:var(--blue);
    bottom:0;left:0;width:28%;height:28%;
    border-right:var(--line) solid var(--black);
    border-top:var(--line) solid var(--black);
  }
  .hero-art .yellow{
    background:var(--yellow);
    bottom:0;right:0;width:34%;height:22%;
    border-left:var(--line) solid var(--black);
    border-top:var(--line) solid var(--black);
  }
  .hero-text{
    display:flex;
    flex-direction:column;
    justify-content:center;
    gap:clamp(16px,2.5vw,28px);
    padding:clamp(20px,3vw,40px) 0;
  }
  h1{
    font-weight:900;
    font-size:clamp(2rem,5.5vw,4.2rem);
    line-height:1.02;
    letter-spacing:-.02em;
  }
  h1 .accent{color:var(--red);}
  .sub{
    font-size:clamp(1rem,2vw,1.35rem);
    font-weight:500;
    max-width:34ch;
  }
  .meta{
    display:flex;
    flex-wrap:wrap;
    gap:10px;
  }
  .chip{
    border:3px solid var(--black);
    padding:.4em .9em;
    font-weight:700;
    font-size:.85rem;
    text-transform:uppercase;
    letter-spacing:.06em;
  }
  .chip.red{background:var(--red);color:var(--white);}
  .chip.blue{background:var(--blue);color:var(--white);}
  .chip.yellow{background:var(--yellow);color:var(--black);}
  .chip.plain{background:var(--white);color:var(--black);}
  .hero-bottom{
    display:grid;
    grid-template-columns:1fr 1fr 1fr;
    gap:var(--line);
    align-items:end;
  }
  .scroll-hint{
    font-weight:700;
    text-transform:uppercase;
    letter-spacing:.12em;
    font-size:.8rem;
    display:flex;
    align-items:center;
    gap:.6em;
  }
  .scroll-hint .arrow{
    width:14px;height:14px;
    border-right:3px solid var(--black);
    border-bottom:3px solid var(--black);
    transform:rotate(45deg);
  }
  .hero-bottom .spacer{background:var(--grey);}
  .hero-bottom .spacer{height:10px;}
  /* ---------- SECTIONS ---------- */
  section{padding:clamp(48px,8vw,96px) clamp(24px,5vw,64px);}
  .section-head{
    display:grid;
    grid-template-columns:120px 1fr;
    gap:20px;
    margin-bottom:clamp(28px,4vw,48px);
    align-items:start;
  }

